(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*14;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.33)*12;
  const x2 = x+w1x, y2 = y+w1y;
  const w2x = Math.sin(x2*0.025-t*0.5)*10 + Math.cos(y2*0.02+t*0.4)*8;
  const w2y = Math.cos(y2*0.022+t*0.45)*9 + Math.sin(x2*0.028-t*0.38)*7;
  const sx = x2+w2x, sy = y2+w2y;
  const src = [
    [120+Math.sin(t*0.6)*80, 60+Math.cos(t*0.4)*40, 0.09, 2.1, 1.0],
    [360+Math.cos(t*0.5)*90, 80+Math.sin(t*0.7)*50, 0.07, 1.8, 0.8],
    [200+Math.sin(t*0.35+2)*120, 40+Math.cos(t*0.55+1)*70, 0.065, 2.4, 1.2],
    [80+Math.cos(t*0.8+1)*70, 180+Math.sin(t*0.6+3)*50, 0.11, 1.6, 0.9],
    [400+Math.sin(t*0.45+4)*80, 180+Math.cos(t*0.9+2)*60, 0.08, 2.7, 1.1],
    [240+Math.cos(t*0.38+5)*100, 220+Math.sin(t*0.58)*70, 0.075, 2.0, 0.85],
    [160+Math.sin(t*0.72+3)*60, 130+Math.cos(t*0.48+4)*55, 0.1, 2.3, 1.05],
    [320+Math.cos(t*0.42+1)*75, 120+Math.sin(t*0.65+2)*65, 0.085, 1.9, 0.95]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.5) * w;
    hS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.0) * w * 0.5;
  }
  const tw = src.reduce((a,s)=>a+s[4],0);
  const act = aS/tw, inh = iS/tw, har = hS/tw;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.9) + Math.sin(sx*0.028-sy*0.038+t*1.2))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.8)*0.18 + Math.sin((sx-sy)*0.095-t*2.2)*0.18;
  const bg3 = Math.sin(sx*0.07*Math.cos(t*0.2)+sy*0.05*Math.sin(t*0.15)+t*1.5)*0.12;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.6) + Math.sin(dist*0.038+ang*4.5-t*1.3);
  const sp2 = Math.sin(dist*0.06-ang*2-t*2.1)*0.4 + Math.sin(dist*0.025+ang*6-t*0.9)*0.3;
  const spiral = (sp1*0.35 + sp2);
  const vor = Math.min(Math.min(Math.abs(Math.sin(sx*0.13)), Math.abs(Math.sin(sy*0.13))), Math.abs(Math.sin((sx+sy)*0.092)));
  const cell = Math.tanh((vor - 0.15)*6)*0.25;
  const lap = (Math.sin(sx*0.08+0.5)*Math.sin(sy*0.08+0.5) + Math.sin(sx*0.08-0.5)*Math.sin(sy*0.08-0.5) - 2*Math.sin(sx*0.08)*Math.sin(sy*0.08))*0.5;
  const rd = Math.tanh((act - inh*0.72 + bg*0.28 + spiral*0.35 + cell + lap*0.15 + har*0.2)*2.0);
  const pulse = 0.92 + Math.sin(t*0.8)*0.08;
  const v = Math.max(0, Math.min(1, rd*0.5*pulse + 0.5));
  const pal = [
    [6, 12, 52], [12, 45, 85], [18, 88, 118], [25, 138, 135],
    [65, 178, 148], [160, 200, 110], [220, 195, 75], [235, 155, 85],
    [215, 105, 95], [175, 60, 85], [120, 35, 75], [60, 18, 60], [6, 12, 52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const c0 = pal[i], c1 = pal[i+1];
  const reactAbs = Math.abs(rd);
  const lum = 0.82 + reactAbs*0.18;
  const edge = reactAbs > 0.65 ? 1.0 + (reactAbs-0.65)*0.8 : 1.0;
  const shimmer = 1.0 + Math.sin(rd*12 + t*4)*0.04*reactAbs;
  const m = lum * edge * shimmer;
  return [
    Math.min(255, (c0[0]+(c1[0]-c0[0])*f)*m)|0,
    Math.min(255, (c0[1]+(c1[1]-c0[1])*f)*m)|0,
    Math.min(255, (c0[2]+(c1[2]-c0[2])*f)*m)|0
  ];
}
